<?php if(!isAdmin()){flash('error','Acesso restrito ao administrador.');redirect('index.php?page=dashboard');}
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();$action=$_POST['action']??'';if($action==='save'){$name=trim($_POST['name']);$email=trim($_POST['email']);$role=in_array($_POST['role']??'', ['admin','manager','cashier'],true)?$_POST['role']:'cashier';$pass=$_POST['password'];if(!$pass){flash('error','Informe uma senha.');redirect('index.php?page=users');}$pdo->prepare('INSERT INTO users(name,email,password,role,active) VALUES(?,?,?,?,1)')->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);flash('success','Usuário criado.');redirect('index.php?page=users');}if($action==='toggle'){$id=(int)$_POST['id'];if($id!==$_SESSION['user']['id'])$pdo->prepare('UPDATE users SET active=1-active WHERE id=?')->execute([$id]);redirect('index.php?page=users');}}
$rows=$pdo->query('SELECT id,name,email,role,active,created_at FROM users ORDER BY id DESC')->fetchAll();$title='Usuários';require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Usuários e permissões</h1><p>Administrador, gerente e operador de caixa.</p></div></div><div class="grid two"><section class="panel"><h2>Novo usuário</h2><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save"><label>Nome<input name="name" required></label><label>E-mail<input name="email" type="email" required></label><label>Senha<input name="password" type="password" required></label><label>Perfil<select name="role"><option value="cashier">Operador de caixa</option><option value="manager">Gerente</option><option value="admin">Administrador</option></select></label><button class="btn primary">Cadastrar</button></form></section><section class="panel"><h2>Equipe</h2><table><thead><tr><th>Usuário</th><th>Perfil</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $u):?><tr><td><strong><?=e($u['name'])?></strong><small><?=e($u['email'])?></small></td><td><?=e($u['role'])?></td><td><?=$u['active']?'Ativo':'Inativo'?></td><td><?php if($u['id']!=$_SESSION['user']['id']):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="link-btn"><?=$u['active']?'Desativar':'Ativar'?></button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></section></div><?php require __DIR__.'/../../includes/footer.php';?>
